const SAYS_DEFAULT = "question";
const IMP = {
  "rim": 106,
  "size": 1,
  "height": 1,
  "drops": 1
};
const IMP_SPEED = 1;
const IMP_INK = "#ffd84d";
const DROP_SLOTS = 34;


export type FleurMood = "idle" | "listening" | "thinking" | "excited" | "happy" | "sad" | "angry" | "surprised" | "confused" | "curious" | "shy" | "wink" | "squint" | "sideEye" | "alert" | "scan" | "lookAround" | "peek" | "nod" | "shakeNo" | "bored" | "sleepy" | "yawn" | "sleep" | "meditate" | "bounce" | "dance" | "spin" | "tumble" | "dizzy";

export type FleurSays = "hmm" | "question" | "zzz" | "aha" | "smitten" | "oh" | "yes" | "nope" | "meh" | "grr" | "wow" | "woozy" | "none";

export interface FleurCharacterProps {
  mood?: FleurMood;
  /** What it says. Its own mood comes with it; "none" is a plain character. */
  says?: FleurSays;
  interactive?: boolean;
  /** Draw one frame, then stop scheduling while paused. */
  paused?: boolean;
  /** Fine mouse only; subtle head/eye turn without moving the SVG container. */
  followPointer?: boolean;
  /** Compact top-only impression reserve for small, non-flipping app avatars. */
  framing?: "safe" | "compact";
  /** Hold displays a completed symbol immediately; cycle keeps the export's liquid animation. */
  impressionPlayback?: "cycle" | "hold";
  /**
   * Draw the texture this character was exported wearing. On by default,
   * because the default of a param is the value it replaced — what you
   * downloaded is what you get.
   *
   * It works by putting the texture id back to "none", which is the same thing
   * the studio's own picker does, so "off" is not a second rendering path: it
   * is the character with no texture, exactly as if none had been chosen. The
   * SwiftUI and React Native components take the same flag, spelled the same.
   */
  texture?: boolean;
  className?: string;
}

// One node per overlay the engine can emit, assigned by INDEX. Sized on the
// worst case (a glass body playing Shy with a coloured topper is five), not on
// the common one — anything past the pool is silently dropped.
const OVERLAY_SLOTS = 6;
const OVERLAY_POOL = ["ov0", "ov1", "ov2", "ov3", "ov4", "ov5"];

const DROP_POOL = Array.from({ length: DROP_SLOTS }, (_, i) => "imp-d" + i);
type SvgNodes = Record<string, SVGElement | null>;

function lay(node: SVGElement | null | undefined, d: string, op: string) {
  if (!node) return;
  node.setAttribute("d", d || "M0 0");
  node.setAttribute("opacity", d ? op : "0");
}

// The texture's layers, back to front — the skin this character was exported
// wearing, if it was wearing one. A fixed pool assigned BY INDEX, the same rule
// the overlays follow: a renderer that enumerates names silently drops whatever
// the engine grows next. Every value comes off the FRAME, colours included —
// the engine decided them, like everything else in this file.
const TEXTURE_SLOTS = 4;
const TEXTURE_POOL = Array.from({ length: TEXTURE_SLOTS }, (_, i) => "tex" + i);

function applyTexture(e: SvgNodes, frame: SvgFrame) {
  for (let i = 0; i < TEXTURE_SLOTS; i++) {
    const n = e["tex" + i];
    if (!n) continue;
    const t = frame.texture[i];
    if (!t) { n.setAttribute("opacity", "0"); n.setAttribute("d", "M0 0"); continue; }
    n.setAttribute("d", t.d || "M0 0");
    n.setAttribute("fill", t.fill);
    n.setAttribute("stroke", t.stroke);
    n.setAttribute("stroke-width", t.width);
    n.setAttribute("opacity", t.d ? t.op : "0");
  }
}

// The emotion flush — Angry's red face, Shy's blush. Both are colours the
// engine already mixed; this only writes them, and puts the body's own back
// when the flush is gone.
export function applyFlush(e: SvgNodes, frame: SvgFrame, paint: BodyPaint, blushId: string) {
  const r = frame.ramp;
  if (e.stop0) e.stop0.setAttribute("stop-color", r ? r.light : paint.light);
  if (e.stop1) e.stop1.setAttribute("stop-color", r ? r.mid : paint.mid);
  if (e.stop2) e.stop2.setAttribute("stop-color", r ? r.dark : paint.dark);
  // ITERATE THE LIST; NEVER ENUMERATE IDS. This used to walk a hard-coded
  // ["topper","cheekL","cheekR"], which meant any overlay the engine grew
  // afterwards was computed, shipped, and drawn as nothing — invisible to
  // every gate here, because the gates compare NUMBERS and the numbers were
  // right. Assigning by index from the pool is what makes a new overlay
  // (a specular glint, say) render in a download without this file changing.
  for (let i = 0; i < OVERLAY_SLOTS; i++) {
    const node = e["ov" + i];
    if (!node) continue;
    const v = frame.overlays[i];
    if (!v) { node.setAttribute("opacity", "0"); continue; }
    node.setAttribute("d", v.d);
    node.setAttribute("fill", v.fill);
    node.setAttribute("opacity", v.op);
    node.setAttribute("filter", v.blur ? "url(#" + blushId + ")" : "none");
  }
}


// The gooey merge: a blur, then an alpha ramp steep enough to snap the blurred
// edges back to hard ones, so two droplets that overlap become one blob.
const heldImpressions = new WeakMap<ImpressionPlan, SvgImpression>();
export function heldImpression(plan: ImpressionPlan): SvgImpression {
  const cached = heldImpressions.get(plan);
  if (cached) return cached;
  // The last text letter only starts settling at setT. Wait 400ms so it is
  // complete, then freeze the glyph without the export's later drip/retract.
  const rendered = svgImpression(impressionFrame(plan, { ...IMP, t: plan.setT + 400 }));
  const held = { ...rendered, drops: [] };
  heldImpressions.set(plan, held);
  return held;
}

export function fleurViewBox(extent: number, plan: ImpressionPlan | null, framing: "safe" | "compact" = "safe") {
  const top = plan ? Math.max(extent, impressionReach(IMP)) : extent;
  if (!plan || framing !== "compact") return [-top, -top, top * 2, top * 2];
  const glyph = impressionFrame(plan, { ...IMP, t: plan.setT + 400 }).glyph;
  let glyphHalfWidth = 0;
  let glyphTop = 0;
  for (let i = 0; glyph && i < glyph.pts.length; i += 2) {
    glyphHalfWidth = Math.max(glyphHalfWidth, Math.abs(glyph.pts[i]));
    glyphTop = Math.max(glyphTop, Math.abs(glyph.pts[i + 1]));
  }
  // Task moods roll by <=14deg plus a small ambient offset. Include an 18deg
  // envelope and filter margin, without paying for a full 360deg square.
  const halfWidth = Math.max(extent, glyphHalfWidth + glyphTop * Math.sin(Math.PI / 10) + 10);
  return [-halfWidth, -top, halfWidth * 2, top + extent];
}

function applyImpression(e: SvgNodes, plan: ImpressionPlan | null, t: number, hold = false) {
  if (!plan) {
    for (let i = 0; i < DROP_SLOTS; i++) { const n = e["imp-d" + i]; if (n) n.setAttribute("r", "0"); }
    if (e["imp-glyph"]) e["imp-glyph"].setAttribute("opacity", "0");
    return;
  }
  const v = hold ? heldImpression(plan) : svgImpression(impressionFrame(plan, { ...IMP, t: t * IMP_SPEED }));
  for (let i = 0; i < DROP_SLOTS; i++) {
    const node = e["imp-d" + i];
    if (!node) continue;
    const d = v.drops[i];
    if (!d) { node.setAttribute("r", "0"); continue; }
    node.setAttribute("cx", d.cx);
    node.setAttribute("cy", d.cy);
    node.setAttribute("r", d.r);
  }
  const g = e["imp-glyph"];
  if (g) {
    g.setAttribute("d", v.glyphD || "M0 0");
    g.setAttribute("opacity", v.glyphD ? v.glyphOpacity : "0");
  }
}

function applyEye(sclera: SVGElement | null | undefined, iris: SVGElement | null | undefined, pupil: SVGElement | null | undefined, glint: SVGElement | null | undefined, g: SvgEye | null) {
  if (!g) {
    lay(sclera, "", "0");
    lay(iris, "", "0");
    lay(pupil, "", "0");
    lay(glint, "", "0");
    return;
  }
  lay(sclera, g.d, g.op);
  lay(iris, g.id, g.pop);
  lay(pupil, g.pd, g.pop);
  lay(glint, g.gd, g.pop);
}

export const FLEUR_MOODS = ["idle", "listening", "thinking", "excited", "happy", "sad", "angry", "surprised", "confused", "curious", "shy", "wink", "squint", "sideEye", "alert", "scan", "lookAround", "peek", "nod", "shakeNo", "bored", "sleepy", "yawn", "sleep", "meditate", "bounce", "dance", "spin", "tumble", "dizzy"] as const satisfies readonly FleurMood[];
export const FLEUR_SAYS = ["hmm", "question", "zzz", "aha", "smitten", "oh", "yes", "nope", "meh", "grr", "wow", "woozy", "none"] as const satisfies readonly FleurSays[];
const moods = new Set<string>(FLEUR_MOODS);
const sayings = new Set<string>(FLEUR_SAYS);
export function isFleurMood(value: unknown): value is FleurMood { return typeof value === "string" && moods.has(value); }
export function isFleurSays(value: unknown): value is FleurSays { return typeof value === "string" && sayings.has(value); }

